INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'dk-b2g-2005', id, '2005-01-01', 1, 'https://erhvervsstyrelsen.dk' FROM countries WHERE name_en = 'Denmark';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('dk-b2g-2005', 'en', 'Public-sector invoicing already digital', 'Denmark has run digital B2G invoicing for two decades — the 2022 Bookkeeping Act extends the underlying discipline to the private sector rather than inventing something new.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'dk-act-2022', id, '2022-05-24', 1, 'https://erhvervsstyrelsen.dk' FROM countries WHERE name_en = 'Denmark';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('dk-act-2022', 'en', 'Bogføringsloven (Bookkeeping Act), Act No. 700, passed', 'Establishes the modern digital bookkeeping framework, replacing the regime that had governed Danish bookkeeping since 2006.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'dk-regulation-2024', id, '2024-02-29', 1, 'https://erhvervsstyrelsen.dk' FROM countries WHERE name_en = 'Denmark';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('dk-regulation-2024', 'en', 'Implementing regulation published (Bekendtgørelse nr. 205)', 'Sets out the detailed technical criteria for both registered and non-registered digital bookkeeping systems.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'dk-established', id, '2024-07-01', 1, 'https://erhvervsstyrelsen.dk' FROM countries WHERE name_en = 'Denmark';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('dk-established', 'en', 'Digital Bookkeeping Act enforced — medium/large companies (in force since Jul 2024)', 'Medium and large companies filing annual reports must use a certified digital bookkeeping system capable of sending and receiving structured e-invoices (OIOUBL or Peppol BIS 3.0) and generating SAF-T files on request.', '["Confirm your bookkeeping system is on the Danish Business Authority''s certified list, or ensure compliance yourself if using a custom system", "Maintain 5-year digital records with automated off-site backup"]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'dk-phasein', id, '2026-01-01', 1, 'https://erhvervsstyrelsen.dk' FROM countries WHERE name_en = 'Denmark';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('dk-phasein', 'en', 'Phased rollout completes across company types', 'Starting with privately owned companies above DKK 300,000 turnover, extending through to financial companies of any size and personally-owned companies above the same threshold by 1 January 2026.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'dk-oioubl3-cancelled', id, '2026-01-01', 1, 'https://erhvervsstyrelsen.dk' FROM countries WHERE name_en = 'Denmark';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('dk-oioubl3-cancelled', 'en', 'OIOUBL 3.0 cancelled', 'The planned next major version of Denmark''s national format is scrapped entirely — OIOUBL 2.1 remains the operative standard with no direct replacement, pending the Peppol-based migration below.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'dk-nemhandel-default', id, '2026-07-01', 0, 'https://erhvervsstyrelsen.dk' FROM countries WHERE name_en = 'Denmark';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('dk-nemhandel-default', 'en', 'NemHandel-by-default campaign begins', 'Erhvervsstyrelsen automatically enrols all entities on registered bookkeeping systems into NemHandel, prompting default e-invoice issuance with an opt-out window — a nudge toward actual usage, not just capability.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'dk-small', id, '2026-07-01', 0, 'https://erhvervsstyrelsen.dk' FROM countries WHERE name_en = 'Denmark';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('dk-small', 'en', 'Small businesses (>DKK 300,000 turnover) with custom systems must comply', 'Small businesses and sole proprietorships exceeding DKK 300,000 turnover in two consecutive years, using non-registered ("custom") accounting systems, become fully subject to the Bookkeeping Act''s digital requirements.', '["Check whether your turnover has crossed the DKK 300,000 threshold in the last two fiscal years", "Businesses on registered/certified systems already needed to comply from January 2026"]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'dk-saft2027', id, '2027-01-01', 0, 'https://erhvervsstyrelsen.dk' FROM countries WHERE name_en = 'Denmark';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('dk-saft2027', 'en', 'Danish SAF-T 2.0 generation required', 'Entities on registered bookkeeping systems must be able to generate a Danish Standard Audit File for Tax on demand — SAF-T 2.0 will harmonise charts of accounts and VAT codes nationally.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'dk-bis4-rc', id, '2027-11-01', 0, 'https://erhvervsstyrelsen.dk' FROM countries WHERE name_en = 'Denmark';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('dk-bis4-rc', 'en', 'NemHandel BIS 4 release candidate', 'A proposed version of Denmark''s localised Peppol BIS 4 format (incorporating the PINT architecture) is released for stakeholder comment.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'dk-oioubl-phaseout', id, '2029-05-01', 0, 'https://erhvervsstyrelsen.dk' FROM countries WHERE name_en = 'Denmark';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('dk-oioubl-phaseout', 'en', 'OIOUBL 2.1 fully phased out', 'Denmark completes its migration to NemHandel BIS 4 / Peppol PINT — timed deliberately to align with the EU ViDA cross-border deadline of 1 July 2030.', '[]');
